"use client"

import type React from "react"

import { useState } from "react"
import { motion } from "framer-motion"
import Link from "next/link"
import Header from "@/components/Header"
import Footer from "@/components/Footer"
import PageTransition from "@/components/PageTransition"
import { ChevronLeft, Check } from "lucide-react"

export default function CheckoutPage() {
  const [currentStep, setCurrentStep] = useState<"shipping" | "payment" | "review">("shipping")
  const [isProcessing, setIsProcessing] = useState(false)
  const [orderConfirmed, setOrderConfirmed] = useState(false)

  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phone: "",
    address: "",
    city: "",
    postalCode: "",
  })

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target
    setFormData((prev) => ({ ...prev, [name]: value }))
  }

  const handleShippingSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    setCurrentStep("payment")
  }

  const handlePaymentSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    setCurrentStep("review")
  }

  const handlePlaceOrder = async () => {
    setIsProcessing(true)
    await new Promise((resolve) => setTimeout(resolve, 2000))
    setOrderConfirmed(true)
    setIsProcessing(false)
  }

  const steps = [
    { id: "shipping", label: "Shipping" },
    { id: "payment", label: "Payment" },
    { id: "review", label: "Review" },
  ]

  if (orderConfirmed) {
    return (
      <div className="min-h-screen flex flex-col bg-white">
        <Header cartCount={0} />
        <PageTransition>
          <div className="flex-1 flex items-center justify-center px-4 py-20">
            <motion.div
              initial={{ scale: 0, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              transition={{ duration: 0.5, ease: "easeOut" }}
              className="text-center max-w-md"
            >
              <motion.div
                initial={{ scale: 0 }}
                animate={{ scale: 1 }}
                transition={{ delay: 0.2, duration: 0.5 }}
                className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-green-100 mb-6"
              >
                <Check className="w-10 h-10 text-green-600" />
              </motion.div>
              <h1 className="text-4xl font-bold mb-4">Order Confirmed!</h1>
              <p className="text-gray-600 mb-8">
                Thank you for your purchase. Your order has been received and is being processed.
              </p>
              <Link
                href="/"
                className="inline-block bg-black text-white px-8 py-3 font-semibold hover:bg-gray-800 transition"
              >
                Continue Shopping
              </Link>
            </motion.div>
          </div>
        </PageTransition>
        <Footer />
      </div>
    )
  }

  return (
    <div className="min-h-screen flex flex-col bg-white">
      <Header cartCount={0} />
      <PageTransition>
        <div className="flex-1 max-w-4xl mx-auto w-full px-4 py-12">
          <Link href="/shop" className="flex items-center text-gray-600 hover:text-gray-900 mb-8">
            <ChevronLeft size={20} />
            Back to Shop
          </Link>

          <h1 className="text-4xl font-bold mb-8">Checkout</h1>

          {/* Progress Steps */}
          <div className="mb-12">
            <div className="flex items-center justify-between">
              {steps.map((step, index) => (
                <motion.div
                  key={step.id}
                  className="flex flex-1 items-center"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ delay: index * 0.1 }}
                >
                  <motion.div
                    whileHover={{ scale: 1.1 }}
                    className={`flex h-10 w-10 items-center justify-center rounded-full border-2 font-semibold ${
                      currentStep === step.id ? "border-black bg-black text-white" : "border-gray-300 text-gray-600"
                    }`}
                  >
                    {index + 1}
                  </motion.div>
                  <div className={`flex-1 h-1 mx-2 ${index < steps.length - 1 ? "bg-gray-300" : ""}`} />
                </motion.div>
              ))}
            </div>
          </div>

          {/* Form Content */}
          <motion.div
            key={currentStep}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            transition={{ duration: 0.3 }}
            className="bg-gray-50 p-8 rounded-lg mb-8"
          >
            {currentStep === "shipping" && (
              <form onSubmit={handleShippingSubmit} className="space-y-6">
                <h2 className="text-2xl font-bold mb-6">Shipping Information</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <motion.input
                    whileFocus={{ scale: 1.02 }}
                    type="text"
                    name="firstName"
                    placeholder="First Name"
                    value={formData.firstName}
                    onChange={handleInputChange}
                    required
                    className="px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-black"
                  />
                  <motion.input
                    whileFocus={{ scale: 1.02 }}
                    type="text"
                    name="lastName"
                    placeholder="Last Name"
                    value={formData.lastName}
                    onChange={handleInputChange}
                    required
                    className="px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-black"
                  />
                </div>
                <motion.input
                  whileFocus={{ scale: 1.02 }}
                  type="email"
                  name="email"
                  placeholder="Email"
                  value={formData.email}
                  onChange={handleInputChange}
                  required
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-black"
                />
                <motion.input
                  whileFocus={{ scale: 1.02 }}
                  type="tel"
                  name="phone"
                  placeholder="Phone Number"
                  value={formData.phone}
                  onChange={handleInputChange}
                  required
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-black"
                />
                <motion.input
                  whileFocus={{ scale: 1.02 }}
                  type="text"
                  name="address"
                  placeholder="Address"
                  value={formData.address}
                  onChange={handleInputChange}
                  required
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-black"
                />
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <motion.input
                    whileFocus={{ scale: 1.02 }}
                    type="text"
                    name="city"
                    placeholder="City"
                    value={formData.city}
                    onChange={handleInputChange}
                    required
                    className="px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-black"
                  />
                  <motion.input
                    whileFocus={{ scale: 1.02 }}
                    type="text"
                    name="postalCode"
                    placeholder="Postal Code"
                    value={formData.postalCode}
                    onChange={handleInputChange}
                    required
                    className="px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-black"
                  />
                </div>
                <motion.button
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  type="submit"
                  className="w-full bg-black text-white py-3 font-semibold rounded-lg hover:bg-gray-800 transition"
                >
                  Continue to Payment
                </motion.button>
              </form>
            )}

            {currentStep === "payment" && (
              <form onSubmit={handlePaymentSubmit} className="space-y-6">
                <h2 className="text-2xl font-bold mb-6">Payment Information</h2>
                <motion.input
                  whileFocus={{ scale: 1.02 }}
                  type="text"
                  placeholder="Cardholder Name"
                  required
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-black"
                />
                <motion.input
                  whileFocus={{ scale: 1.02 }}
                  type="text"
                  placeholder="Card Number"
                  required
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-black"
                />
                <div className="grid grid-cols-2 gap-4">
                  <motion.input
                    whileFocus={{ scale: 1.02 }}
                    type="text"
                    placeholder="MM/YY"
                    required
                    className="px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-black"
                  />
                  <motion.input
                    whileFocus={{ scale: 1.02 }}
                    type="text"
                    placeholder="CVV"
                    required
                    className="px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-black"
                  />
                </div>
                <div className="flex gap-4">
                  <motion.button
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                    type="button"
                    onClick={() => setCurrentStep("shipping")}
                    className="flex-1 border-2 border-black text-black py-3 font-semibold rounded-lg hover:bg-gray-100 transition"
                  >
                    Back
                  </motion.button>
                  <motion.button
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                    type="submit"
                    className="flex-1 bg-black text-white py-3 font-semibold rounded-lg hover:bg-gray-800 transition"
                  >
                    Review Order
                  </motion.button>
                </div>
              </form>
            )}

            {currentStep === "review" && (
              <div className="space-y-6">
                <h2 className="text-2xl font-bold mb-6">Review Your Order</h2>
                <div className="bg-white p-6 rounded-lg space-y-4">
                  <div>
                    <h3 className="font-semibold text-gray-900">Shipping To:</h3>
                    <p className="text-gray-600">
                      {formData.firstName} {formData.lastName}
                    </p>
                    <p className="text-gray-600">{formData.address}</p>
                    <p className="text-gray-600">
                      {formData.city}, {formData.postalCode}
                    </p>
                  </div>
                  <div className="border-t pt-4">
                    <h3 className="font-semibold text-gray-900 mb-2">Order Summary</h3>
                    <div className="flex justify-between text-gray-600 mb-2">
                      <span>Subtotal:</span>
                      <span>$99.99</span>
                    </div>
                    <div className="flex justify-between text-gray-600 mb-4">
                      <span>Shipping:</span>
                      <span>$10.00</span>
                    </div>
                    <div className="flex justify-between font-bold text-lg border-t pt-4">
                      <span>Total:</span>
                      <span>$109.99</span>
                    </div>
                  </div>
                </div>
                <div className="flex gap-4">
                  <motion.button
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                    type="button"
                    onClick={() => setCurrentStep("payment")}
                    className="flex-1 border-2 border-black text-black py-3 font-semibold rounded-lg hover:bg-gray-100 transition"
                  >
                    Back
                  </motion.button>
                  <motion.button
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                    onClick={handlePlaceOrder}
                    disabled={isProcessing}
                    className="flex-1 bg-black text-white py-3 font-semibold rounded-lg hover:bg-gray-800 transition disabled:opacity-50"
                  >
                    {isProcessing ? "Processing..." : "Place Order"}
                  </motion.button>
                </div>
              </div>
            )}
          </motion.div>
        </div>
      </PageTransition>
      <Footer />
    </div>
  )
}
